    /**
     * Kecamatan milik satu kabupaten/kota.
     *
     * @return array<int, array{id_kec: string, nama_kec: string, bbox: array<int, float>|null}>
     */
    public static function kecamatans(string $idKab): array
    {
        foreach (self::kabupatens() as $kabupaten) {
            if ($kabupaten['id_kab'] === $idKab) {
                return $kabupaten['kecamatans'];
            }
        }

        return [];
    }
